Given an array arr[] of positive integers, find the Mean and Median, and return the floor of both values.Note: Mean is the average of all elements in the array and Median is the middle value when the array is sorted, if the number of elements is even, it's the average of the two middle values.Examples: Input: arr[] = [1, 2, 19, 28, 5]Output: 11 5Explanation: Sorted array - [1, 2, 5, 19, 28], Mean = (1 + 2 + 19 + 28 + 5) / 5 = 55 / 5 = 11, Median = Middle element = 5Input: arr[] = [2, 8, 3, 4]Output: 4 3Explanation: Sorted array - [2, 3, 4, 8], Mean = (2 + 3 + 4 + 8) / 4 = 17 / 4 = 4.25, so floor(4.25) is 4, Median = (3 + 4)/2 = 3.5, so floor(3.5) is 3Try It Yourself[Approach] Using Definition of Mean and Median Mean (Average) : The mean is calculated by adding all elements of the array and dividing the sum by the total number of elements.Formula: Mean = (a0 + a1 + a2 + --- + an-1) / n Median: The median represents the middle value in a sorted array.Steps to find the median:Sort the array in non-decreasing order.If the number of elements is: => Odd: Median = value at the middle index, Median = an/2th element=> Even: Median = average of the two middle elements, Median = (an/2-1 + an/2) / 2.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int mean(vector<int>& arr) {

    int sum = 0;
    for (int num : arr) {
        sum += num;
    }

    // we can calculate sum by using this function 
    // accumulate(arr.begin(),arr.end(),0);

    // floor of the mean
    return sum / arr.size(); 
}

int median(vector<int>& arr) {

    int n = arr.size();

    // sorting the arrat 'arr' using built in functions 
    sort(arr.begin(), arr.end());
    int result = 0;

    // if there are two middle element
    if (n % 2 == 0) {
        result = (arr[n / 2] + arr[(n / 2) - 1]) / 2;  
    } 
    // if there are only one middle element 
    else {
        result = arr[n / 2];
    }

    return result;
}

int main() {

    vector<int> arr = {2, 3, 4, 8}; 

    int meanValue = mean(arr);
    int medianValue = median(arr);

    cout << meanValue << " " << medianValue << endl;

    return 0;
}


            C

    #include <stdio.h>
#include <stdlib.h>

// comparator for qsort
int compare(const void* a, const void* b) {
    return (*(int*)a - *(int*)b);
}

int mean(int arr[], int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += arr[i];
    }

    // floor of the mean
    return sum / n;
}

int median(int arr[], int n) {

    // sorting function 
    qsort(arr, n, sizeof(int), compare);
    int result = 0;

    // if there are two middle element
    if (n % 2 == 0) {
        result = (arr[n / 2] + arr[(n / 2) - 1]) / 2;
    } 
    // if there are only one middle element 
    else {
        result = arr[n / 2];
    }

    return result;
}

int main() {
    int arr[] = {2, 3, 4, 8};
    int n = sizeof(arr) / sizeof(arr[0]);

    int meanValue = mean(arr, n);
    int medianValue = median(arr, n);

    printf("%d %d\n", meanValue, medianValue);

    return 0;
}


